 ***/
function isArrivalTimelineRowStatus(status) {
	const normalized =
		typeof status === "string" ? status.trim().toLowerCase() : "";
	return (
		normalized === "moved" ||
		normalized.startsWith("moved ") ||
		normalized === "advanced" ||
		normalized.startsWith("advanced ") ||
		normalized === "failed back" ||
		normalized.startsWith("failed back ")
	);
}

